  {"id": "avian_alarm_project", "name": "Avian Alarm", "kind": "personal", "description": "Speranzans have noticed that some birds are sensitive to atmospheric changes, and have taken to designing multi-tiered alarm systems to warn of impending danger. Though their precision has been debated, the calming effect of their companionship is beyond reproach.\n\nSpring 2026 seasonal project tied to ship-model trinkets (Riven Tides era). Phase 1 was an interact task (deploy a bird trap next to the Buoys) rewarding a skill-point token.", "phases": [{"phase": 1, "name": "Initial Flock Intake", "description": "Deploy a bird trap next to the Buoys", "requirements": [{"item": "ARC damage tiers 1", "qty": 1}]}, {"phase": 2, "name": "Preliminary Signal Birds", "description": "Preliminary Signal Birds", "requirements": [{"item": "Tick Pod", "qty": 7}, {"item": "Canister", "qty": 20}, {"item": "Moss", "qty": 12}, {"item": "\"Twilight Compass\" Ship Model", "qty": 5}]}, {"phase": 3, "name": "Secondary Validation Birds", "description": "Secondary Validation Birds", "requirements": [{"item": "Comet Igniter", "qty": 3}, {"item": "Fertilizer", "qty": 10}, {"item": "Rusted Tools", "qty": 8}, {"item": "\"Velocity\" Ship Model", "qty": 5}]}, {"phase": 4, "name": "Heightened Alert Birds", "description": "Heightened Alert Birds", "requirements": [{"item": "Vaporizer Regulator", "qty": 1}, {"item": "Water Filter", "qty": 3}, {"item": "Agave", "qty": 8}, {"item": "\"Sirena Dorata\" Ship Model", "qty": 5}]}, {"phase": 5, "name": "Critical Warning Birds", "description": "Critical Warning Birds", "requirements": [{"item": "Turbine Compressor", "qty": 2}, {"item": "Red Coral Jewelry", "qty": 3}, {"item": "Roots", "qty": 4}, {"item": "\"Leviathan's Crown\" Ship Model", "qty": 1}]}], "startDate": "2026-04-14", "endDate": "2026-05-26", "rewards": [], "verified": false},
  {"id": "flickering_flames_project", "name": "Flickering Flames", "kind": "personal", "description": "A festival of resilient warmth, centered around the hardy candleberry bush. Speranzans have been known to host local celebrations, and being competitive, they seek to outdo each other at every turn. Some have managed to turn the homely candleberry bush into a banquet worthy of even the most discerning gourmands.\n\nCold Snap (Dec 2025) winter festival event: gather Candleberries and festive items across five phases.", "phases": [{"phase": 1, "name": "Candlelight", "description": "The namesake use for the candleberry, Speranzans boil the fruit into a thick wax that burns cleanly and fragrantly.", "requirements": [{"item": "Empty Wine Bottle", "qty": 1}, {"item": "Plastic Parts", "qty": 25}, {"item": "Durable Cloth", "qty": 5}, {"item": "Candleberries", "qty": 20}]}, {"phase": 2, "name": "Decorations", "description": "Many Speranzans have become surprisingly adept at the art of bringing beauty and greenery into the home.", "requirements": [{"item": "Candle Holder", "qty": 3}, {"item": "Light Bulb", "qty": 3}, {"item": "Industrial Battery", "qty": 1}, {"item": "Candleberries", "qty": 50}]}, {"phase": 3, "name": "Presents", "description": "Crafty Speranzans have turned the candleberries into a wealth of gifts. These include perfumes and soaps, as well as gifts unrelated to the recipient's odors.", "requirements": [{"item": "Snap Blast Grenade", "qty": 5}, {"item": "Duct Tape", "qty": 10}, {"item": "Film Reel", "qty": 1}, {"item": "Candleberries", "qty": 60}]}, {"phase": 4, "name": "Beverages", "description": "Candleberries can be crushed into refreshing juices, while the leaves and roots make for a tea that can drive out the toughest of colds.", "requirements": [{"item": "Coffee Pot", "qty": 2}, {"item": "Fireball Burner", "qty": 10}, {"item": "Water Filter", "qty": 2}, {"item": "Candleberries", "qty": 60}]}, {"phase": 5, "name": "Meals", "description": "Though candleberry leaves are bitter, simmering them in stew and soups adds a touch of earthiness that nostalgic Speranzans have grown to love.", "requirements": [{"item": "Mushroom", "qty": 7}, {"item": "Frying Pan", "qty": 2}, {"item": "Music Album", "qty": 2}, {"item": "Candleberries", "qty": 70}]}], "rewards": [], "verified": false},
  {"id": "weather_monitor_system_project", "name": "Weather Monitor System", "kind": "personal", "description": "Collect the required parts to build a private weather station, and help monitor the turbulent weather above.\n\nJan-Mar 2026 personal project: build a private weather station (five phases: pressure, sunlight, precipitation, humidity, temperature).", "phases": [{"phase": 1, "name": "Atmospheric pressure", "description": "Lets you measure if that heavy weight on your shoulders is actually just the air.", "requirements": [{"item": "Plastic Parts", "qty": 25}, {"item": "Metal Parts", "qty": 15}, {"item": "ARC Alloy", "qty": 5}, {"item": "Oil", "qty": 3}]}, {"phase": 2, "name": "Sunlight", "description": "Sunlight might be sparse in Speranza, but ultraviolet rays can still be measured by the right equipment.", "requirements": [{"item": "Snitch Scanner", "qty": 1}, {"item": "Wires", "qty": 3}, {"item": "Sensors", "qty": 3}, {"item": "Comet Igniter", "qty": 1}]}, {"phase": 3, "name": "Precipitation", "description": "Very few parts of Speranza are completely waterproof. Now you can say it’s for science.", "requirements": [{"item": "ARC Powercell", "qty": 5}, {"item": "Canister", "qty": 5}, {"item": "Steel Spring", "qty": 5}, {"item": "Fine Wristwatch", "qty": 1}]}, {"phase": 4, "name": "Humidity", "description": "Great for keeping your skin looking luminous, and your walls somewhat moldy.", "requirements": [{"item": "Duct Tape", "qty": 10}, {"item": "Rusted Bolts", "qty": 3}, {"item": "Water Pump", "qty": 1}, {"item": "Wasp Driver", "qty": 3}]}, {"phase": 5, "name": "Temperature", "description": "Significantly more accurate than counting shivers per minute.", "requirements": [{"item": "Camera Lens", "qty": 3}, {"item": "Damaged Heat Sink", "qty": 1}, {"item": "Firefly Burner", "qty": 1}, {"item": "Voltage Converter", "qty": 3}]}], "startDate": "2026-01-23", "endDate": "2026-03-31", "rewards": [], "verified": false},
  {"id": "high_gain_antenna_project", "name": "High-Gain Antenna", "kind": "personal", "description": "When placed in open areas, these parabolic dishes can pick up on distant signals within a narrow beamwidth, which may help triangulate the origins of the troubling ARC signals that were recently reported.\n\nFeb-Apr 2026 project (Flashpoint era): build a parabolic dish to triangulate troubling ARC signals; heavy on ARC-alloy materials.", "phases": [{"phase": 1, "name": "Sturdy Base", "description": "An extra-sturdy base that can withstand anything from bitter winds to sudden cloudbursts.", "requirements": [{"item": "ARC Alloy", "qty": 50}, {"item": "ARC Flex Rubber", "qty": 10}, {"item": "ARC Performance Steel", "qty": 10}, {"item": "Advanced ARC Powercell", "qty": 15}]}, {"phase": 2, "name": "Data Logger", "description": "A closed-circuit interface to monitor and analyze distributed data points over time.", "requirements": [{"item": "ARC Coolant", "qty": 15}, {"item": "ARC Thermo Lining", "qty": 15}, {"item": "Vaporizer Regulator", "qty": 4}, {"item": "Assessor Matrix", "qty": 6}]}, {"phase": 3, "name": "Parabolic Dish", "description": "A custom-built parabolic dish designed to capture distant signals in even the most stormy of conditions.", "requirements": [{"item": "Surveyor Vault", "qty": 10}, {"item": "ARC Synthetic Resin", "qty": 20}, {"item": "Vaporizer Regulator", "qty": 15}, {"item": "Assessor Matrix", "qty": 18}]}], "startDate": "2026-02-13", "endDate": "2026-04-27", "rewards": [], "verified": false},
  {"id": "converging_paths_project", "name": "Converging Paths", "kind": "personal", "description": "With ARC operations spreading across the Rust Belt, the nomads have agreed to share their knowledge in exchange for support. Raiders are needed to gather supplies, recover relics, and help secure safe passage for nomads traveling through dangerous routes.\n\nMay-Jul 2026 nomad project: damage ARC in the Swamp, collect relics/trinkets, build emergency caches, and use mines/traps.", "phases": [{"phase": 1, "name": "Secure Safe Passage for the Nomads", "description": "Deal Damage to ARC enemies in the Swamp", "requirements": []}, {"phase": 2, "name": "Collect Supplies", "description": "Collect supplies to share with the nomads", "requirements": [{"item": "Train Model", "qty": 3}, {"item": "Vintage Steering Wheel", "qty": 2}, {"item": "Air Freshener", "qty": 2}, {"item": "ARC Thermo Lining", "qty": 6}]}, {"phase": 3, "name": "Procure Relics", "description": "Find relics to share with the nomads", "requirements": [{"item": "Sextant", "qty": 4}, {"item": "Equatorial Sundial", "qty": 3}, {"item": "Metal Brackets", "qty": 5}, {"item": "ARC Performance Steel", "qty": 7}]}, {"phase": 4, "name": "Create Emergency Caches", "description": "Build emergency caches to help both the nomads and Raiders stay alive on the surface", "requirements": [{"item": "Tellurion", "qty": 3}, {"item": "Elephant Obelisk", "qty": 1}, {"item": "Light Bulb", "qty": 6}, {"item": "ARC Coolant", "qty": 9}]}, {"phase": 5, "name": "Finish the Cabinet of Curiosities", "description": "Put the finishing touches on the cabinet of curiosities, a new emblem of blossoming ties between the nomads and Speranza.", "requirements": [{"item": "Colorful Shoes (Red)", "qty": 6}, {"item": "Colorful Shoes (Green)", "qty": 3}, {"item": "Colorful Shoes (Silver)", "qty": 2}, {"item": "ARC Synthetic Resin", "qty": 10}]}, {"phase": 6, "name": "Use Nomad Tactics to Fight ARC", "description": "Deal damage to ARC using mines or traps (Blaze Grenade Trap, Pulse Mine, Jolt Mine, Explosive Mine, Surge Coil)", "requirements": []}], "startDate": "2026-05-11", "endDate": "2026-07-28", "rewards": [], "verified": false},
  {"id": "phantom_targets_project", "name": "Phantom Targets", "kind": "personal", "description": "Unrecognizable noise has started flooding Shani's radars, and she can't pinpoint the origin of these phantom targets. Raider assistance is needed to improve antennas on the surface, and track ARC behavior for any changes.\n\nAug 2026 Part 1 (Shani): upgrade Cargo Elevator antennas, damage ARC with Wasp Drivers/Pop Triggers/Leaper Pulse Units, destroy ARC with fire, energy and launcher ammo.", "phases": [{"phase": 1, "name": "Upgrade Cargo Elevator Antennas", "description": "Upgrade antennas found on top of any Cargo Elevator", "requirements": []}, {"phase": 2, "name": "Test ARC Parts for Irregular Behavior", "description": "Deal damage to ARC enemies using Wasp Drivers, Pop Triggers and Leaper Pulse Units", "requirements": []}, {"phase": 3, "name": "Test Multiple ARC Destruction Methods", "description": "Destroy ARC enemies using fire damage, energy damage, and launcher ammo", "requirements": []}], "startDate": "2026-08-04", "endDate": "2026-09-07", "rewards": [], "verified": false},
  {"id": "phantom_targets_part_2_project", "name": "Phantom Targets", "kind": "personal", "description": "The phantom targets Shani was tracking have a source: some Wasps are exhibiting patterns we've never seen before. They seem frantic.\n\nAug 18 - Sep 7 2026 Part 2 (Live Update 1.42.0): collect Glitched Wasp parts (new item drops from frantic Wasps); rewards include the Anomalia Outfit; finale is damaging flying ARC with Fireworks.", "phases": [{"phase": 1, "name": "Bring In Glitched Wasp Parts for Testing", "description": "Collect glitched Wasp parts", "requirements": [{"item": "Glitched ARC Power Converter", "qty": 10}, {"item": "Glitched ARC Transmitter", "qty": 10}, {"item": "Glitched ARC Phased Array", "qty": 10}, {"item": "Advanced ARC Powercell", "qty": 10}]}, {"phase": 2, "name": "Perform Final Tests on Glitched Wasp Parts", "description": "Collect glitched Wasp parts", "requirements": [{"item": "Glitched ARC Light Ring", "qty": 10}, {"item": "Glitched ARC Circuitry", "qty": 10}, {"item": "ARC Thermo Lining", "qty": 10}, {"item": "ARC Circuitry", "qty": 10}]}, {"phase": 3, "name": "Conduct One Final Explosive Test", "description": "Deal damage to any flying ARC using Fireworks", "requirements": []}], "startDate": "2026-08-18", "endDate": "2026-09-07", "rewards": [], "verified": false},
  {"id": "ascending_the_mountain_project", "name": "Ascending The Mountain", "kind": "personal", "description": "Raider Project introduced with Live Update 1.45.0 (headline of the update). Four phases of item submissions themed around high-altitude / rocket research.\n\nItem names derived from item ids (repo has no English labels for this project yet). Rewards not captured in the data source.", "phases": [{"phase": 1, "name": "Research High-Altitude Mechanics", "description": "", "requirements": [{"item": "Mechanical Components", "qty": 10}, {"item": "Pop Trigger", "qty": 6}, {"item": "Explosive Compound", "qty": 10}, {"item": "Headphones", "qty": 2}]}, {"phase": 2, "name": "Begin Ignition Tests", "description": "", "requirements": [{"item": "Wires", "qty": 20}, {"item": "Voltage Converter", "qty": 8}, {"item": "Sentinel Firing Core", "qty": 2}, {"item": "Rocket Thruster", "qty": 1}]}, {"phase": 3, "name": "Implement Landing Capabilities", "description": "", "requirements": [{"item": "Ruined Parachute", "qty": 2}, {"item": "Crash Mat", "qty": 10}, {"item": "Shredder Gyro", "qty": 5}, {"item": "Breathtaking Snow Globe", "qty": 3}]}, {"phase": 4, "name": "Final Tweaks", "description": "", "requirements": [{"item": "Sensors", "qty": 30}, {"item": "Broken Guidance System", "qty": 3}, {"item": "Advanced Electrical Components", "qty": 15}, {"item": "Vaporizer Regulator", "qty": 3}]}], "startDate": "2026-09-08", "endDate": "2026-10-07", "rewards": [], "verified": false}
